const body = $input.first().json.body || {};
const text = (body.transcript || body.summary || '').toLowerCase();

// Classify Temperature
let temperature = 'UNKNOWN';
let status = 'CALLED';
if (text.includes('urgent') || text.includes('ready to build') || text.includes('send invoice') || text.includes('hot') || (text.includes('website') && text.includes('this week'))) {
  temperature = 'HOT';
  status = 'HOT';
} else if (text.includes('interested') || text.includes('send details') || text.includes('whatsapp') || text.includes('call back')) {
  temperature = 'WARM';
  status = 'INTERESTED';
} else if (text.includes('not interested') || text.includes('no thanks') || text.includes('don\'t call')) {
  temperature = 'COLD';
  status = 'NOT_INTERESTED';
}

// Check DNC Opt-Out
const isDNC = text.includes('don\'t call') || text.includes('remove my number') || text.includes('stop calling');
if (isDNC) {
  status = 'DO_NOT_CALL';
}

// Classify Website Need
let websiteNeed = 'UNKNOWN';
if (text.includes('menu') || text.includes('restaurant')) websiteNeed = 'RESTAURANT_WEBSITE';
else if (text.includes('booking') || text.includes('appointment')) websiteNeed = 'BOOKING_WEBSITE';
else if (text.includes('e-commerce') || text.includes('shop') || text.includes('products')) websiteNeed = 'ECOMMERCE';
else if (text.includes('website')) websiteNeed = 'BASIC_BUSINESS_WEBSITE';

return [{
  json: {
    lead_id: body.lead_id,
    lead_temperature: temperature,
    status: status,
    do_not_call: isDNC,
    website_need: websiteNeed,
    business_goal: text.includes('whatsapp') ? 'WHATSAPP_LEADS' : 'MORE_ENQUIRIES',
    timeline: text.includes('this week') ? 'THIS_WEEK' : (text.includes('this month') ? 'THIS_MONTH' : 'NO_TIMELINE'),
    summary: body.summary || 'Post-call AI classification completed'
  }
}];
